//! A small library.

/// A number.
pub const N: u32 = 3;

/// Three letters.
pub const KEYS: [&str; 3] = ["A", "B", "C"];

/// What the kit is called.
pub const NAME: &str = "conformance kit";

/// Bounds, by size.
pub const LIMITS: [(&str, u32); 1] = [("small", 1)];

/// Adds two numbers.
///
/// ```
/// assert_eq!(kit::add(1, 2), 3);
/// ```
pub fn add(a: i64, b: i64) -> i64 {
    a + b
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn adds() {
        assert_eq!(add(1, 2), 3);
    }
}

