//! The runners of the tables on the pages.

use std::collections::HashMap;

/// The runners of cases tables, by name.
pub const CASES: &[(&str, fn(&HashMap<String, String>) -> Result<(), String>)] = &[("adds", adds)];

fn adds(row: &HashMap<String, String>) -> Result<(), String> {
    let number = |column: &str| row[column].parse::<i64>().unwrap_or(0);
    let got = kit::add(number("a"), number("b")).to_string();
    if got == row["sum"] { Ok(()) } else { Err(format!("expected {}, got {got}", row["sum"])) }
}

